fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> Vec<char> {
    // Determine the smaller length to avoid out-of-bounds access
    let min_len = std::cmp::min(str1.len(), str2.len());
    // Preallocate result with the maximum possible size
    let mut result = Vec::with_capacity(min_len);

    // Compare characters one by one
    for i in 0..min_len {
        if str1[i] == str2[i] {
            result.push(str1[i]);
        } else {
            break;
        }
    }

    result
}

fn main() {
    let a: Vec<char> = "flower".chars().collect();
    let b: Vec<char> = "flow".chars().collect();
    let c: Vec<char> = "flight".chars().collect();
    let d: Vec<char> = "".chars().collect();

    assert_eq!(longest_common_prefix(&a, &b), "flow".chars().collect::<Vec<_>>());
    assert_eq!(longest_common_prefix(&a, &c), "fl".chars().collect::<Vec<_>>());
    assert_eq!(longest_common_prefix(&a, &d), Vec::<char>::new());
    println!("All tests passed!");
}